SELECT  -- account.main
    (f.facility_id) AS account_key,
    (f.facility_number) AS account_number,
    CASE (f.product) WHEN 'CC' THEN 'CASH_CREDIT' WHEN 'OD' THEN 'OVERDRAFT' WHEN 'TOD' THEN 'TEMPORARY_OVERDRAFT' WHEN 'CORPCARD' THEN 'CORPORATE_CREDIT_CARD' WHEN 'DL' THEN 'DEMAND_LOAN' WHEN 'TL_SHORT' THEN 'SHORT_TERM_LOAN' WHEN 'TL_MED' THEN 'MEDIUM_TERM_LOAN' WHEN 'TL_LONG' THEN 'LONG_TERM_LOAN' WHEN 'WCL' THEN 'WORKING_CAPITAL_LOAN' WHEN 'BG' THEN 'BANK_GUARANTEE' WHEN 'LC' THEN 'LETTER_OF_CREDIT' WHEN 'CVL' THEN 'COMMERCIAL_VEHICLE_LOAN' WHEN 'EQP' THEN 'COMMERCIAL_EQUIPMENT_LOAN' WHEN 'FACT_R' THEN 'FACTORING_WITH_RECOURSE' WHEN 'FACT_NR' THEN 'FACTORING_WITHOUT_RECOURSE' WHEN 'PCL' THEN 'PACKING_CREDIT' WHEN 'EBD' THEN 'EXPORT_BILLS_DISCOUNTED' WHEN 'MUDRA_TL' THEN 'MUDRA_TERM_LOAN' WHEN 'MUDRA_WC' THEN 'MUDRA_WORKING_CAPITAL' WHEN 'BLU' THEN 'BUSINESS_LOAN_UNSECURED' ELSE (f.product) END AS account_type,
    (f.sanction_date) AS date_opened,
    (f.last_paid_date) AS date_last_payment,
    (f.closed_date) AS date_closed,
    NULL AS date_reported,
    (f.high_credit) AS high_credit_amount,
    (f.outstanding) AS current_balance,
    (f.overdue) AS amount_overdue,
    (f.dpd) AS days_past_due,
    CASE (f.suit_status) WHEN 'NONE' THEN 'NO_SUIT_FILED' WHEN 'FILED' THEN 'SUIT_FILED' WHEN 'TRIAL' THEN 'TRIAL_IN_PROGRESS' WHEN 'DECREE' THEN 'DECREE_ISSUED' WHEN 'EXECUTION' THEN 'DECREE_EXECUTION' WHEN 'NCLT' THEN 'NCLT_SUIT_FILED' ELSE (f.suit_status) END AS suit_filed_status,
    CASE (f.status) WHEN 'WO' THEN 'WRITTEN_OFF' WHEN 'RESTRUCT' THEN 'RESTRUCTURED_LOAN' WHEN 'RESTRUCT_GOVT' THEN 'RESTRUCTURED_LOAN_GOVT_MANDATED' WHEN 'RESTRUCT_CALAMITY' THEN 'RESTRUCTURED_DUE_TO_NATURAL_CALAMITY' WHEN 'RESTRUCT_COVID' THEN 'RESTRUCTURED_DUE_TO_COVID_19' WHEN 'ARC_SOLD' THEN 'SOLD_TO_ARC' WHEN 'ARC_PURCHASED' THEN 'PURCHASED_FROM_BANK' ELSE (f.status) END AS credit_facility_status,
    CASE (f.asset_class) WHEN 'STD' THEN 'STANDARD' WHEN 'SUB' THEN 'SUBSTANDARD' WHEN 'SMA0' THEN 'SMA_0' WHEN 'SMA1' THEN 'SMA_1' WHEN 'SMA2' THEN 'SMA_2' WHEN 'DBT1' THEN 'DOUBTFUL_1' WHEN 'DBT2' THEN 'DOUBTFUL_2' WHEN 'DBT3' THEN 'DOUBTFUL_3' WHEN 'ARC' THEN 'ARC_LOAN' ELSE (f.asset_class) END AS asset_classification,
    NULL AS collateral_value,
    NULL AS collateral_type,
    NULL AS credit_limit,
    NULL AS cash_limit,
    NULL AS rate_of_interest,
    (f.tenure_months) AS repayment_tenure,
    (f.instalment) AS emi_amount,
    (f.written_off) AS written_off_total,
    NULL AS written_off_principal,
    (f.settled) AS settlement_amount,
    CASE (f.frequency) WHEN 'HALFYEARLY' THEN 'HALF_YEARLY' WHEN 'ONDEMAND' THEN 'ON_DEMAND' WHEN 'OTHER' THEN 'OTHERS' ELSE (f.frequency) END AS payment_frequency,
    (f.last_paid) AS actual_payment_amount,
    NULL AS old_member_code,
    NULL AS old_member_short_name,
    NULL AS old_account_number,
    NULL AS old_account_type,
    NULL AS old_ownership_indicator,
    (f.branch_code) AS branch_code,
    NULL AS previous_branch_code,
    NULL AS previous_account_number,
    (f.sanction_amount) AS sanctioned_amount,
    (f.currency) AS currency,
    (f.drawing_power) AS drawing_power,
    NULL AS restructured_notional_amount,
    (f.maturity_date) AS maturity_date,
    (f.renewal_date) AS renewal_date,
    (f.asset_class_date) AS asset_classification_date,
    (f.bucket_1) AS overdue_bucket_1,
    (f.bucket_2) AS overdue_bucket_2,
    (f.bucket_3) AS overdue_bucket_3,
    (f.bucket_4) AS overdue_bucket_4,
    (f.bucket_5) AS overdue_bucket_5,
    (f.status_date) AS status_date,
    CASE (f.restructure_reason) WHEN 'NPA' THEN 'NON_PERFORMANCE' WHEN 'CALAMITY' THEN 'NATURAL_CALAMITY' WHEN 'COVID' THEN 'COVID_19' WHEN 'OTHER' THEN 'OTHERS' ELSE (f.restructure_reason) END AS restructuring_reason,
    NULL AS npa_contracts_amount,
    (f.security_cover) AS security_coverage,
    (f.guarantee_cover) AS guarantee_coverage,
    (f.remark) AS remark,
    (f.wilful_date) AS wilful_default_date,
    (f.suit_ref) AS suit_reference,
